//! The factory of a host environment's wheel (SPEC 14.4.1, ADR-0065 item
//! 3): `make(*, num_envs, seed, auto_reset, max_episode_steps, workers,
//! cpu_set, **config)`, generated by [`export_host_env!`].
//!
//! The pool options come from the named keywords; every other keyword is
//! the environment's config, decoded by its `ConfigDecode` (the decoder the
//! Rust factory uses, [`super::config`]). The factory returns a host object
//! holding the pool ([`super::object`], SPEC 14.4.2).
//!
//! [`export_host_env!`]: crate::export_host_env

use core::num::{NonZeroU32, NonZeroUsize};

use tessera_rl_core::config::{CanonicalConfig, canonical_bytes};
use tessera_rl_core::{ConfigDecode, HostEnvironment};
use tessera_rl_engine::{AutoReset, DynHostPool, EngineError, HostPool, PoolOptions, SyncOptions};
use tessera_rl_num::identity::Seed;

use super::config;
use super::object::{self, HOST_TYPE, HostBody};
use crate::errors::{self, Kind as ErrorKind};
use crate::ffi::capi::{self, CResult, Gil, Kind, Mine, Ref};

/// Initializes a host module: binds `tessera_rl`'s exception classes
/// (SPEC 14.4.6) and adds the host object type. Called by the module
/// [`export_host_env!`](crate::export_host_env) generates.
///
/// # Errors
///
/// `ImportError` when `tessera_rl` or one of its classes is missing, or a
/// failure to create the type.
pub fn init(g: Gil<'_>, module: Ref<'_>) -> CResult<()> {
    errors::bind(g)?;
    object::register(g, module)
}

/// The pool options of `make`, read from its named keywords.
struct Options {
    pool: PoolOptions,
    sync: Option<SyncOptions>,
}

const NAMED: [&str; 6] = [
    "num_envs",
    "seed",
    "auto_reset",
    "max_episode_steps",
    "workers",
    "cpu_set",
];

fn argument(g: Gil<'_>, message: String) -> capi::Raised {
    errors::error(g, ErrorKind::Argument, message)
}

/// A named keyword's conversion: a value of the wrong type or range (a
/// `TypeError` or `OverflowError` from the conversion) is an
/// `ArgumentError` naming it, as `tessera_rl.make` raises. Any other
/// exception (none is expected: the conversions of exact built-in types
/// run no Python code) propagates unchanged.
fn option<T>(g: Gil<'_>, r: CResult<T>, name: &str, expected: &str) -> CResult<T> {
    r.map_err(|raised| {
        if capi::pending_is_conversion_error(g) {
            capi::clear_pending(g);
            argument(g, format!("make: {name} must be {expected}"))
        } else {
            raised
        }
    })
}

/// Splits `make`'s keywords into the pool options and the config entries.
fn options<'py>(
    g: Gil<'py>,
    kwargs: Vec<(String, Mine<'py>)>,
) -> CResult<(Options, Vec<(String, Mine<'py>)>)> {
    let (named, rest): (Vec<_>, Vec<_>) = kwargs
        .into_iter()
        .partition(|(k, _)| NAMED.contains(&k.as_str()));
    let get = |name: &str| {
        named
            .iter()
            .find(|(k, _)| k == name)
            .map(|(_, v)| v.as_ref())
    };
    let num_envs = get("num_envs")
        .ok_or_else(|| argument(g, "make: num_envs is required".to_owned()))
        .and_then(|v| option(g, capi::to_u32(g, v, "num_envs"), "num_envs", "an int"))?;
    let num_envs = NonZeroU32::new(num_envs)
        .ok_or_else(|| argument(g, "make: num_envs must be at least 1".to_owned()))?;
    let seed = match get("seed") {
        Some(v) if capi::kind(v) != Kind::None => option(
            g,
            capi::to_u64(g, v, "seed"),
            "seed",
            "None or an int in [0, 2**64)",
        )?,
        _ => 0,
    };
    let mut pool = PoolOptions::new(num_envs, Seed::new(seed));
    if let Some(v) = get("auto_reset").filter(|v| capi::kind(*v) != Kind::None) {
        let mode = option(
            g,
            capi::to_string(g, v, "auto_reset"),
            "auto_reset",
            "a str",
        )?;
        pool.auto_reset = match mode.as_str() {
            "next_step" => AutoReset::NextStep,
            "same_step" => AutoReset::SameStep,
            "disabled" => AutoReset::Disabled,
            other => {
                return Err(argument(
                    g,
                    format!("make: auto_reset {other:?} is not next_step, same_step or disabled"),
                ));
            }
        };
    }
    if let Some(v) = get("max_episode_steps").filter(|v| capi::kind(*v) != Kind::None) {
        let steps = option(
            g,
            capi::to_u32(g, v, "max_episode_steps"),
            "max_episode_steps",
            "None or an int",
        )?;
        pool.max_episode_steps =
            Some(NonZeroU32::new(steps).ok_or_else(|| {
                argument(g, "make: max_episode_steps must be at least 1".to_owned())
            })?);
    }
    let workers = match get("workers") {
        Some(v) if capi::kind(v) != Kind::None => {
            option(g, capi::to_u64(g, v, "workers"), "workers", "an int")?
        }
        _ => 0,
    };
    let workers = usize::try_from(workers)
        .map_err(|_| argument(g, "make: workers is out of range".to_owned()))?;
    let cpu_set = match get("cpu_set") {
        Some(v) if capi::kind(v) != Kind::None => Some(
            option(
                g,
                capi::list_items(g, v, "cpu_set"),
                "cpu_set",
                "None or a list of ints",
            )?
            .iter()
            .map(|c| {
                option(
                    g,
                    capi::to_u64(g, c.as_ref(), "cpu_set"),
                    "cpu_set",
                    "a list of ints",
                )
                .and_then(|c| {
                    usize::try_from(c)
                        .map_err(|_| argument(g, "make: cpu_set is out of range".to_owned()))
                })
            })
            .collect::<CResult<Vec<usize>>>()?,
        ),
        _ => None,
    };
    let sync = match NonZeroUsize::new(workers) {
        Some(n) => Some(SyncOptions {
            cpu_set,
            ..SyncOptions::new(n)
        }),
        None if cpu_set.is_some() => {
            return Err(argument(g, "make: cpu_set needs workers >= 1".to_owned()));
        }
        None => None,
    };
    Ok((Options { pool, sync }, rest))
}

/// Reads the config keywords and decodes `C` (the shared decoder): key
/// names first, then values.
fn decode_config<C: ConfigDecode>(g: Gil<'_>, entries: Vec<(String, Mine<'_>)>) -> CResult<C> {
    let kwargs = config::read(g, entries)?.map_err(|e| config::raise_kwargs(g, &e))?;
    config::decode_kwargs::<C>(&kwargs).map_err(|r| config::raise_refusal(g, &r))
}

fn engine(g: Gil<'_>, e: &EngineError) -> capi::Raised {
    errors::error(g, errors::engine_kind(e), e.to_string())
}

fn keywords<'py>(
    g: Gil<'py>,
    args: Ref<'_>,
    kwargs: Option<Ref<'_>>,
    what: &str,
) -> CResult<Vec<(String, Mine<'py>)>> {
    if !capi::tuple_items(g, args, what)?.is_empty() {
        return Err(argument(g, format!("{what}: keyword arguments only")));
    }
    match kwargs {
        Some(k) => capi::dict_items(g, k, what),
        None => Ok(Vec::new()),
    }
}

/// `make(*, num_envs, seed, auto_reset, max_episode_steps, workers,
/// cpu_set, **config)` for `E` with `A = E::MAX_AGENTS` (SPEC 14.4.1 item
/// 4). Not public API: [`export_host_env!`](crate::export_host_env) calls
/// it.
///
/// # Errors
///
/// `ArgumentError` for positional arguments, a missing pool option, a
/// pool option of the wrong type or range (as `tessera_rl.make`), or an
/// unknown config key (reported before any value's type); `ConfigError`
/// for a config value of a type no field takes, a config that does not
/// decode or validate, or action heads outside protocol 1; the engine's
/// construction errors. The six named keywords are reserved: no config
/// field can be set through them.
#[doc(hidden)]
pub fn make<'py, E, const A: usize>(
    g: Gil<'py>,
    args: Ref<'py>,
    kwargs: Option<Ref<'py>>,
) -> CResult<Mine<'py>>
where
    E: HostEnvironment,
    E::Config: ConfigDecode,
{
    let (options, entries) = options(g, keywords(g, args, kwargs, "make")?)?;
    let cfg: E::Config = decode_config(g, entries)?;
    let mut pool = HostPool::<E, A>::new(&cfg, options.pool).map_err(|e| engine(g, &e))?;
    // Protocol 1 carries discrete heads only, or one continuous head.
    let (discrete, continuous) = pool.action_heads();
    if !((discrete > 0 && continuous == 0) || (discrete == 0 && continuous == 1)) {
        // Dropping a pool can block (host code): not under the GIL.
        g.detach(move || drop(pool));
        return Err(errors::error(
            g,
            ErrorKind::Config,
            "make: host protocol 1 carries discrete heads only, or exactly one continuous head"
                .to_owned(),
        ));
    }
    if let Some(sync) = options.sync {
        // Detached: starting workers can block, and on failure the pool is
        // dropped inside `with_workers`, which can block too (host code).
        pool = g
            .detach(move || pool.with_workers(sync))
            .map_err(|e| engine(g, &e))?;
    }
    let pool: Box<dyn DynHostPool> = Box::new(pool);
    let storage = match pool.outputs() {
        Ok(out) => out.storage(),
        Err(e) => {
            let raised = engine(g, &e);
            // Dropping a pool can block (host code): not under the GIL.
            g.detach(move || drop(pool));
            return Err(raised);
        }
    };
    // An allocation failure here drops the pool under the interpreter: the
    // object is not created, so there is no other place to drop it.
    HOST_TYPE.instantiate(g, HostBody::new(pool, storage))
}

/// The canonical form (ADR-0030) of `C` decoded from keyword arguments
/// with the shared decoder: what the Python front end makes of them, for
/// the comparison with the Rust front end (`bytes`).
///
/// # Errors
///
/// As [`make`]'s config errors.
pub fn config_canonical<'py, C>(
    g: Gil<'py>,
    args: Ref<'py>,
    kwargs: Option<Ref<'py>>,
) -> CResult<Mine<'py>>
where
    C: ConfigDecode + CanonicalConfig,
{
    let entries = keywords(g, args, kwargs, "config")?;
    let cfg: C = decode_config(g, entries)?;
    capi::bytes(g, &canonical_bytes(&cfg))
}

/// Exports a host environment's wheel (SPEC 14.4, ADR-0065 item 3): the
/// module `$module` (its qualified name, a C string literal) with the host
/// object type and `make(*, num_envs, seed, auto_reset, max_episode_steps,
/// workers, cpu_set, **config)`, initialized by the fixed
/// `PyInit__tessera_host` (feature `host`). `$env::Config` must implement
/// `ConfigDecode` (derive `EnvConfig`). `functions` appends module
/// functions of the crate's own.
///
/// Expand it once, in the cdylib's own crate (ADR-0054). Its expansion
/// contains no `unsafe`.
///
/// ```ignore
/// tessera_rl_pyffi::export_host_env!(my_env::Book, module = c"book_env._tessera_host");
/// ```
#[macro_export]
macro_rules! export_host_env {
    ($env:ty, module = $module:literal) => {
        $crate::export_host_env!($env, module = $module, functions = []);
    };
    ($env:ty, module = $module:literal, functions = [$($row:expr),* $(,)?]) => {
        const _: () = {
            struct __Make;
            impl $crate::ffi::module_def::FunctionKw for __Make {
                fn call<'py>(
                    g: $crate::ffi::capi::Gil<'py>,
                    args: $crate::ffi::capi::Ref<'py>,
                    kwargs: ::core::option::Option<$crate::ffi::capi::Ref<'py>>,
                ) -> $crate::ffi::capi::CResult<$crate::ffi::capi::Mine<'py>> {
                    $crate::host::factory::make::<
                        $env,
                        { <$env as $crate::__private::HostEnvironment>::MAX_AGENTS },
                    >(g, args, kwargs)
                }
            }
            static ROWS: &[$crate::ffi::module_def::FunctionRow] = &[
                $crate::ffi::module_def::FunctionRow::kw::<__Make>(
                    c"make",
                    c"make(*, num_envs, seed, auto_reset, max_episode_steps, workers, cpu_set, **config)",
                ),
                $($row,)*
                $crate::ffi::module_def::FunctionRow::END,
            ];
            static TABLE: $crate::ffi::module_def::FunctionTable =
                $crate::ffi::module_def::FunctionTable::new(ROWS);
            static DEF: $crate::ffi::module_def::ModuleDef = $crate::ffi::module_def::ModuleDef::new(
                $module,
                c"A host environment (host protocol 1, SPEC 14.4).",
                &TABLE,
            );
            struct __Init;
            impl $crate::ffi::module_def::ModuleInit for __Init {
                const DEF: &'static $crate::ffi::module_def::ModuleDef = &DEF;
                fn init<'py>(
                    g: $crate::ffi::capi::Gil<'py>,
                    module: $crate::ffi::capi::Ref<'py>,
                ) -> $crate::ffi::capi::CResult<()> {
                    $crate::host::factory::init(g, module)
                }
            }
            $crate::export_module!(host: __Init);
        };
    };
}
